contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmt: amount to deposit first so there is some balance to collect from
    // collectAmt: amount to attempt to collect
    function run(uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this contract can send the requested deposit
        require(address(this).balance >= depositAmt);

        // read balance before any operations
        uint before = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // perform a deposit to ensure there may be funds to collect
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // read balance after deposit and before collect
        uint mid = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // attempt to Collect collectAmt and catch revert
        bool collectReverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        // read final public balance
        uint finalBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General rule:
        // - Collect must never increase the publicly visible balance.
        // - If it reverts, the public balance stays equal to mid.
        // - If it succeeds, the public balance is <= mid and the decrease is at most collectAmt.
        assert((collectReverted && finalBal == mid) || (!collectReverted && finalBal <= mid && mid - finalBal <= collectAmt));
    }

    receive() external payable {}
}

