pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        uint256 before;
        try c.balances(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 mid;
        try c.balances(address(this)) returns (uint256 __r) { mid = __r; } catch { return; }
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 finalBal;
        try c.balances(address(this)) returns (uint256 __r) { finalBal = __r; } catch { return; }
        assertTrue((collectReverted && finalBal == mid) || (!collectReverted && finalBal <= mid && mid - finalBal <= collectAmt));
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt) public {
        _run(depositAmt, collectAmt);
    }

    receive() external payable {}
}
